"""Sound effects generated by our own code (whoosh, impact, riser) — 100% original,
no licenses needed."""
from __future__ import annotations


import numpy as np

SR = 48000


def _env(n: int, attack: float, release: float) -> np.ndarray:
    a, r = int(n * attack), int(n * release)
    e = np.ones(n)
    if a:
        e[:a] = np.linspace(0, 1, a)
    if r:
        e[-r:] = np.linspace(1, 0, r) ** 2
    return e


def whoosh(seconds: float = 0.45, seed: int = 0) -> np.ndarray:
    rng = np.random.default_rng(seed)
    n = int(SR * seconds)
    noise = rng.standard_normal(n)
    # sweep a simple low-pass by mixing smoothed versions over time
    out = np.zeros(n)
    for k, width in enumerate((64, 32, 16, 8)):
        smooth = np.convolve(noise, np.ones(width) / width, mode="same")
        mix = np.clip(np.linspace(-0.5, 1.5, n) - k * 0.35, 0, 1)
        out += smooth * mix
    return 0.5 * out / (np.abs(out).max() + 1e-9) * _env(n, 0.55, 0.45)


def impact(seconds: float = 0.6) -> np.ndarray:
    n = int(SR * seconds)
    t = np.arange(n) / SR
    freq = 90 * np.exp(-t * 6) + 40
    body = np.sin(2 * np.pi * np.cumsum(freq) / SR) * np.exp(-t * 7)
    click = np.random.default_rng(1).standard_normal(n) * np.exp(-t * 60) * 0.3
    sig = body + click
    return 0.8 * sig / (np.abs(sig).max() + 1e-9)


def riser(seconds: float = 1.5) -> np.ndarray:
    n = int(SR * seconds)
    t = np.arange(n) / SR
    freq = np.linspace(200, 1400, n)
    tone = np.sin(2 * np.pi * np.cumsum(freq) / SR)
    noise = np.random.default_rng(2).standard_normal(n) * 0.3
    sig = (tone * 0.4 + noise) * np.linspace(0, 1, n) ** 2
    return 0.4 * sig / (np.abs(sig).max() + 1e-9) * _env(n, 0.0, 0.05)


def pop(seconds: float = 0.14, pitch: float = 900) -> np.ndarray:
    """Bubbly pop for stickers and words appearing."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    freq = pitch * np.exp(-t * 18) + 250
    sig = np.sin(2 * np.pi * np.cumsum(freq) / SR) * np.exp(-t * 30)
    return 0.6 * sig / (np.abs(sig).max() + 1e-9)


def tick(seconds: float = 0.035) -> np.ndarray:
    n = int(SR * seconds)
    t = np.arange(n) / SR
    sig = np.random.default_rng(3).standard_normal(n) * np.exp(-t * 220)
    return 0.5 * sig / (np.abs(sig).max() + 1e-9)


def bass_drop(seconds: float = 1.1) -> np.ndarray:
    """Deep cinematic hit for the hook and the big reveal."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    freq = 70 * np.exp(-t * 2.5) + 32
    body = np.tanh(2.2 * np.sin(2 * np.pi * np.cumsum(freq) / SR)) * np.exp(-t * 2.8)
    sig = body + impact(seconds)[:n] * 0.5
    return 0.9 * sig / (np.abs(sig).max() + 1e-9)


def ding(seconds: float = 0.9, base: float = 880) -> np.ndarray:
    n = int(SR * seconds)
    t = np.arange(n) / SR
    sig = sum(np.sin(2 * np.pi * base * h * t) * np.exp(-t * (3 + h * 2)) / h for h in (1, 2.01, 3.03, 4.2))
    return 0.5 * sig / (np.abs(sig).max() + 1e-9)


# ---------- niche sound palette (research specs, audit 12 Nov; all synthesised here, no licences needed) ----------
def _lp(sig: np.ndarray, width: int) -> np.ndarray:
    return np.convolve(sig, np.ones(width) / width, mode="same")


def conch(seconds: float = 2.2) -> np.ndarray:
    """Shankh: a breathy brass-like drone (fundamental ~233 Hz) with slow swell and a little vibrato (mythology spec)."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    f0 = 233 * (1 + 0.006 * np.sin(2 * np.pi * 5.2 * t)) * (1 + 0.03 * np.clip(t / 0.25, 0, 1))
    ph = 2 * np.pi * np.cumsum(f0) / SR
    tone = sum(np.sin(ph * h) / h ** 1.2 for h in range(1, 9))
    breath = _lp(np.random.default_rng(5).standard_normal(n), 6) * 0.15
    env = np.clip(t / 0.45, 0, 1) ** 1.5 * np.clip((seconds - t) / 0.6, 0, 1)
    sig = np.tanh(1.3 * tone) + breath
    return 0.7 * sig * env / (np.abs(sig * env).max() + 1e-9)


def bell(seconds: float = 2.6, base: float = 523.0) -> np.ndarray:
    """Temple bell: inharmonic partials with a long decay (mythology spec: bell on scene changes)."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    parts = ((0.5, 1.0, 1.4), (1.0, 0.8, 1.9), (1.19, 0.5, 2.3), (1.56, 0.45, 2.9), (2.0, 0.3, 3.6), (2.74, 0.2, 4.4))
    sig = sum(a * np.sin(2 * np.pi * base * r * t) * np.exp(-t * d) for r, a, d in parts)
    strike = np.random.default_rng(6).standard_normal(n) * np.exp(-t * 90) * 0.2
    sig = sig + strike
    return 0.6 * sig / (np.abs(sig).max() + 1e-9)


def heartbeat(seconds: float = 0.9) -> np.ndarray:
    """Lub-dub under number/equation cards (sports spec)."""
    n = int(SR * seconds)
    out = np.zeros(n)
    for at, g in ((0.0, 1.0), (0.2, 0.7)):
        k = int(at * SR)
        m = int(0.16 * SR)
        tt = np.arange(m) / SR
        thump = np.sin(2 * np.pi * (55 * np.exp(-tt * 9) + 38) * tt) * np.exp(-tt * 22) * g
        out[k:k + m] += thump[: n - k]
    return 0.85 * out / (np.abs(out).max() + 1e-9)


def crowd(seconds: float = 2.4, seed: int = 8) -> np.ndarray:
    """Crowd roar swell (band-limited noise with a rising envelope) for the climax (sports spec)."""
    rng = np.random.default_rng(seed)
    n = int(SR * seconds)
    t = np.arange(n) / SR
    noise = _lp(rng.standard_normal(n), 10) - _lp(rng.standard_normal(n), 120) * 0.5
    flutter = 1 + 0.25 * _lp(rng.standard_normal(n), 2400) * 40
    env = np.clip(t / (seconds * 0.6), 0, 1) ** 1.4 * np.clip((seconds - t) / 0.5, 0, 1)
    sig = noise * flutter * env
    return 0.6 * sig / (np.abs(sig).max() + 1e-9)


def kaching(seconds: float = 0.8) -> np.ndarray:
    """Cash-register 'ka-ching' for money numbers (money spec): a click, then two bright bell hits."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    out = np.random.default_rng(9).standard_normal(n) * np.exp(-t * 120) * 0.4
    for at, base in ((0.06, 2093.0), (0.12, 2637.0)):
        k = int(at * SR)
        tt = t[: n - k]
        out[k:] += sum(np.sin(2 * np.pi * base * h * tt) * np.exp(-tt * (6 + 3 * h)) / h for h in (1, 2.4, 3.9))
    return 0.55 * out / (np.abs(out).max() + 1e-9)


def shutter(seconds: float = 0.18) -> np.ndarray:
    """Camera shutter: two quick clicks (movie/newspaper cards)."""
    n = int(SR * seconds)
    out = np.zeros(n)
    rng = np.random.default_rng(10)
    for at in (0.0, 0.07):
        k = int(at * SR)
        m = int(0.03 * SR)
        tt = np.arange(m) / SR
        out[k:k + m] += rng.standard_normal(m) * np.exp(-tt * 260)
    return 0.6 * out / (np.abs(out).max() + 1e-9)


def paper(seconds: float = 0.45) -> np.ndarray:
    """Paper slide (evidence/document cards)."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    noise = np.random.default_rng(11).standard_normal(n)
    sig = (noise - _lp(noise, 20)) * np.sin(np.pi * t / seconds) ** 1.5
    return 0.45 * sig / (np.abs(sig).max() + 1e-9)


def typewriter(seconds: float = 0.5, keys: int = 6) -> np.ndarray:
    """A few typewriter key strikes (quote/clue cards)."""
    n = int(SR * seconds)
    out = np.zeros(n)
    rng = np.random.default_rng(12)
    for k in range(keys):
        at = int((k * seconds / keys + rng.uniform(0, 0.02)) * SR)
        m = int(0.025 * SR)
        tt = np.arange(m) / SR
        hit = (rng.standard_normal(m) * 0.6 + np.sin(2 * np.pi * 1800 * tt)) * np.exp(-tt * 300)
        out[at:at + m] += hit[: max(0, n - at)]
    return 0.6 * out / (np.abs(out).max() + 1e-9)


def tape(seconds: float = 0.5) -> np.ndarray:
    """Tape-rewind squeal, falling pitch (sports spec: rewind into the backstory)."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    freq = 1800 * np.exp(-t * 4) + 300
    tone = np.sin(2 * np.pi * np.cumsum(freq) / SR)
    noise = _lp(np.random.default_rng(13).standard_normal(n), 4) * 0.3
    sig = (tone * 0.5 + noise) * _env(n, 0.05, 0.4)
    return 0.5 * sig / (np.abs(sig).max() + 1e-9)


def impact_soft(seconds: float = 0.45) -> np.ndarray:
    """A low, short thud for cuts (mystery spec: action SFX on 30-50% of cuts, kept subtle)."""
    n = int(SR * seconds)
    t = np.arange(n) / SR
    sig = np.sin(2 * np.pi * (70 * np.exp(-t * 8) + 35) * t) * np.exp(-t * 11)
    return 0.7 * sig / (np.abs(sig).max() + 1e-9)


def breath(seconds: float = 0.22, sr: int = SR, seed: int = 21) -> np.ndarray:
    """A soft, natural inhale (band-limited noise, rise then fall), peak ~0.1. Placed in the narrator's longer pauses."""
    rng = np.random.default_rng(seed)
    n = int(sr * seconds)
    x = rng.standard_normal(n)
    x = np.convolve(x, np.ones(6) / 6, mode="same") - np.convolve(x, np.ones(60) / 60, mode="same")
    env = np.sin(np.pi * np.arange(n) / n) ** 1.5
    y = x * env
    return 0.1 * y / (np.abs(y).max() + 1e-9)


def voice_env(voice: np.ndarray, attack: float = 0.05, release: float = 0.3) -> np.ndarray:
    """0..1 per sample: how much the voice is speaking right now (attack/release smoothed)."""
    v = np.abs(voice if voice.ndim == 1 else voice.mean(axis=1))
    hop = int(0.01 * SR)
    m = len(v) // hop
    if m < 2:
        return np.zeros(len(v), np.float32)
    lvl = v[: m * hop].reshape(m, hop).max(axis=1)
    thr = max(np.percentile(lvl, 60) * 0.25, 1e-4)
    target = (lvl > thr).astype(np.float32)
    env = np.zeros(m, np.float32)
    a = 1 - np.exp(-0.01 / max(attack, 0.005))
    r = 1 - np.exp(-0.01 / max(release, 0.005))
    for i in range(1, m):
        k = a if target[i] > env[i - 1] else r
        env[i] = env[i - 1] + k * (target[i] - env[i - 1])
    return np.repeat(env, hop)


def carve_mid(music: np.ndarray, voice: np.ndarray, db: float = 4.0, lo: float = 1000.0, hi: float = 4000.0,
              attack: float = 0.05, release: float = 0.3) -> np.ndarray:
    """Dynamic EQ (owner 18 Nov research): while the voice speaks, only the music's 1-4 kHz band (where speech
    intelligibility lives and masking happens) dips `db`; bass, beat and air stay, so the music still sounds full.
    Sources: iZotope / Waves dynamic-EQ sidechain guides, ProSoundWeb (masking sits at 1-4 kHz)."""
    if db <= 0 or len(music) < 64:
        return music
    from scipy.signal import butter, sosfiltfilt
    sos = butter(2, [lo, hi], btype="bandpass", fs=SR, output="sos")
    mid = sosfiltfilt(sos, music).astype(music.dtype)
    env = voice_env(voice, attack, release)
    n = min(len(music), len(env))
    g = np.ones(len(music), np.float32)
    g[:n] = 10 ** (-db * env[:n] / 20)
    return (music - mid * (1 - g)).astype(music.dtype)


def duck_db(music: np.ndarray, voice: np.ndarray, db: float = 6.0, attack: float = 0.05,
            release: float = 0.3) -> np.ndarray:
    """Sidechain ducking in dB with attack/release times (mythology spec: 8-12 dB, 150 ms attack, 400 ms release)."""
    if db <= 0:
        return music
    gain = 10 ** (-db * voice_env(voice, attack, release) / 20)
    n = min(len(music), len(gain))
    out = music.copy()
    out[:n] = music[:n] * gain[:n]
    return out


# ---------- background music, generated (100% original) ----------
SCALES = {"minor": [0, 2, 3, 5, 7, 8, 10], "major": [0, 2, 4, 5, 7, 9, 11]}


def _note(semitones_from_a4: float) -> float:
    return 440.0 * 2 ** (semitones_from_a4 / 12)


def _pad(freqs: list[float], n: int, brightness: float = 0.3) -> np.ndarray:
    t = np.arange(n) / SR
    sig = np.zeros(n)
    for f in freqs:
        for k, detune in enumerate((-0.15, 0.0, 0.15)):
            ph = np.random.default_rng(int(f) + k).uniform(0, 6.28)
            ff = f * 2 ** (detune / 12)
            sig += np.sin(2 * np.pi * ff * t + ph) + brightness * np.sin(4 * np.pi * ff * t + ph) / 2
    return sig / (len(freqs) * 3)


# raga-flavoured scales (semitones from Sa): Bhairavi (devotional, sorrow/devotion), Yaman (romance/nostalgia)
RAGA = {"bhairavi": [0, 1, 3, 5, 7, 8, 10, 12], "yaman": [0, 2, 4, 6, 7, 9, 11, 12]}


def _flute(freq: float, seconds: float, rng) -> np.ndarray:
    """A soft bansuri-like note: sine + 2nd/3rd harmonic, slow attack, delayed vibrato, breath noise."""
    m = int(SR * seconds)
    tt = np.arange(m) / SR
    vib = 1 + 0.008 * np.sin(2 * np.pi * 5.0 * tt) * np.clip((tt - 0.25) / 0.4, 0, 1)
    ph = 2 * np.pi * np.cumsum(freq * vib) / SR
    tone = np.sin(ph) + 0.25 * np.sin(2 * ph) + 0.08 * np.sin(3 * ph)
    breath = np.convolve(rng.standard_normal(m), np.ones(12) / 12, mode="same") * 0.12
    env = np.clip(tt / 0.18, 0, 1) * np.clip((seconds - tt) / 0.35, 0, 1)
    return (tone + breath) * env


def _melody(seconds: float, sa: float, raga: str, rng, start: float = 2.0, gap: float = 6.0,
            gain: float = 0.16) -> np.ndarray:
    """Slow, sparse phrases (3-5 notes, long held last note) with silence between them: emotion without clutter."""
    n = int(SR * seconds)
    out = np.zeros(n)
    scale = RAGA[raga]
    at = start
    while at < seconds - 2.5:
        k = int(rng.integers(2, 6))
        idx = int(rng.integers(2, 6))
        for j in range(k):
            idx = int(np.clip(idx + rng.choice([-2, -1, 1, 2]), 0, len(scale) - 1))
            dur = 0.55 if j < k - 1 else 1.8                       # the phrase rests on a long note
            f = sa * 2 * 2 ** (scale[idx] / 12)
            i0 = int(at * SR)
            if i0 >= n:
                break
            note = _flute(f, dur + 0.2, rng)
            e = min(i0 + len(note), n)
            out[i0:e] += note[: e - i0] * gain
            at += dur
        at += gap * (0.7 + 0.6 * rng.random())
    return out


def _indian_bed(seconds: float, mood: str, seed: int = 0) -> np.ndarray:
    """Original beds with an Indian / cinematic colour so every channel sounds different (spam-policy safe):
    devotional (tanpura-like drone + frame drum + temple bell), dhol (festival drum groove), retro (harmonium-like
    chords + light tabla), noir (low pad + clock tick + sparse piano)."""
    rng = np.random.default_rng(seed)
    n = int(SR * seconds)
    t = np.arange(n) / SR
    out = np.zeros(n)

    def hit(at, f0, decay, gain, noise=0.0):
        i0 = int(at * SR)
        if i0 >= n:
            return
        m = min(int(0.6 * SR), n - i0)
        tt = np.arange(m) / SR
        f = f0 * (1 + 0.6 * np.exp(-tt * 30))                     # pitch drop = drum body
        s = np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-tt * decay)
        if noise:
            s += rng.uniform(-1, 1, m) * np.exp(-tt * decay * 3) * noise
        out[i0:i0 + m] += s * gain

    if mood == "devotional":
        sa = 110.0                                                   # Sa = A2, Pa = E3, upper Sa = A3
        cycle = 4.0                                                  # one tanpura cycle: Pa Sa' Sa' Sa
        for k, f in enumerate([sa * 1.5, sa * 2, sa * 2, sa]):
            for c in range(int(seconds / cycle) + 1):
                i0 = int((c * cycle + k * cycle / 4) * SR)
                if i0 >= n:
                    continue
                m = min(int(cycle * SR), n - i0)
                tt = np.arange(m) / SR
                saw = sum(np.sin(2 * np.pi * f * h * tt) / h for h in range(1, 9))      # buzzy, jawari-like
                out[i0:i0 + m] += saw * np.exp(-tt * 0.7) * 0.10
        for b in range(int(seconds / 2.0) + 1):                     # slow frame drum
            hit(b * 2.0, 70, 9, 0.35, 0.15)
            hit(b * 2.0 + 1.0, 110, 14, 0.18, 0.1)
        for b in range(0, int(seconds), 16):                        # temple bell every 16 s
            i0 = int(b * SR)
            m = min(int(3 * SR), n - i0)
            tt = np.arange(m) / SR
            bell = sum(a * np.sin(2 * np.pi * 660 * r * tt) * np.exp(-tt * d)
                       for r, a, d in ((1, 1, 1.2), (2.76, 0.4, 2), (5.4, 0.15, 3)))
            out[i0:i0 + m] += bell * 0.12
        out += _melody(seconds, sa, "bhairavi", rng, start=2.5, gap=5.5, gain=0.15)   # bansuri: devotion / sorrow
    elif mood == "dhol":
        beat = 60 / 112
        for k in range(int(seconds / (beat / 2)) + 1):              # dha-dhin pattern in eighths
            at = k * beat / 2
            build = min(1.0, at / max(seconds * 0.75, 1))            # the groove builds toward the climax
            if k % 4 in (0, 3):
                hit(at, 60, 8, 0.4 + 0.2 * build, 0.2)               # bass side
            if k % 2 == 1:
                hit(at, 320, 22, 0.16 + 0.12 * build, 0.35)          # treble side (stick)
            if build > 0.6 and k % 4 == 2:
                hit(at, 420, 26, 0.12 * build, 0.4)                  # extra fills in the last quarter
        out += np.sin(2 * np.pi * 55 * t) * 0.05 * (0.5 + 0.5 * np.sin(2 * np.pi * t / 8))
    elif mood == "retro":
        chords = [[0, 4, 7], [5, 9, 12], [7, 11, 14], [5, 9, 12]]
        bar = 2.4
        for b in range(int(seconds / bar) + 1):
            i0 = int(b * bar * SR)
            if i0 >= n:
                break
            m = min(int(bar * SR), n - i0)
            tt = np.arange(m) / SR
            seg = np.zeros(m)
            for st in chords[b % 4]:
                f = 220 * 2 ** (st / 12)
                seg += sum(np.sin(2 * np.pi * f * h * tt) / h ** 1.3 for h in range(1, 6))   # reedy, harmonium-like
            out[i0:i0 + m] += seg * np.minimum(1, tt / 0.15) * np.minimum(1, (bar - tt) / 0.2) * 0.05
        beat = 60 / 96
        for k in range(int(seconds / beat) + 1):
            hit(k * beat, 90 if k % 2 == 0 else 260, 12 if k % 2 == 0 else 26, 0.25, 0.15)
        out += _melody(seconds, 220.0, "yaman", rng, start=3.0, gap=6.5, gain=0.10)    # old-Bollywood nostalgia
    else:  # noir
        out += sum(np.sin(2 * np.pi * f * t) for f in (65.4, 98.0, 130.8)) * 0.05 * (0.6 + 0.4 * np.sin(2 * np.pi * t / 11))
        for k in range(int(seconds) + 1):                            # clock tick
            i0 = int(k * SR)
            m = min(int(0.02 * SR), n - i0)
            if m > 0:
                out[i0:i0 + m] += rng.uniform(-1, 1, m) * np.exp(-np.arange(m) / (0.003 * SR)) * 0.08
        for k in range(0, int(seconds), 5):                          # sparse low piano note
            i0 = int((k + 2.5) * SR)
            if i0 >= n:
                continue
            m = min(int(2.5 * SR), n - i0)
            tt = np.arange(m) / SR
            f = rng.choice([110.0, 130.8, 146.8, 98.0])
            out[i0:i0 + m] += sum(np.sin(2 * np.pi * f * h * tt) / h ** 2 for h in (1, 2, 3)) * np.exp(-tt * 1.4) * 0.12
    out *= np.minimum(1, t / 1.5) * np.minimum(1, (seconds - t) / 1.5).clip(0)
    return 0.7 * out / (np.abs(out).max() + 1e-9)


def _doc_bed(seconds: float, mood: str, seed: int = 0) -> np.ndarray:
    """Documentary beds, each channel its own sound: cosmic (slow wide pad + sparse high shimmer), ocean (deep pad
    + slow wave swells), wild (warm pad + soft plucked arpeggio + low hand-drum pulse)."""
    rng = np.random.default_rng(seed)
    n = int(SR * seconds)
    t = np.arange(n) / SR
    roots = {"cosmic": [110.0, 87.3, 98.0, 73.4], "ocean": [82.4, 73.4, 98.0, 65.4], "wild": [130.8, 98.0, 110.0, 87.3]}
    bar = {"cosmic": 8.0, "ocean": 7.0, "wild": 4.0}[mood]
    out = np.zeros(n)
    for b in range(int(seconds / bar) + 1):
        s, e = int(b * bar * SR), min(int((b + 1) * bar * SR + SR), n)
        if s >= n:
            break
        f = roots[mood][b % 4]
        tt = t[s:e] - t[s]
        env = np.minimum(1, tt / (bar * 0.4)) * np.minimum(1, (tt[-1] - tt + 1e-3) / 1.0)
        chord = sum(np.sin(2 * np.pi * f * r * tt + rng.uniform(0, 6)) for r in (1, 1.5, 2, 2.52))
        out[s:e] += chord * env * 0.18
    if mood == "cosmic":                                     # sparse high shimmer
        for _ in range(int(seconds / 1.7)):
            i0 = int(rng.uniform(0, max(1, seconds - 3)) * SR)
            m = min(int(3 * SR), n - i0)
            tt = np.arange(m) / SR
            f = rng.choice([880.0, 1046.5, 1318.5, 1568.0])
            out[i0:i0 + m] += np.sin(2 * np.pi * f * tt) * np.exp(-tt * 1.2) * 0.05
    elif mood == "ocean":                                    # slow wave swells (filtered noise, ~0.08 Hz)
        noise = np.convolve(rng.standard_normal(n), np.ones(400) / 400, mode="same")
        out += noise * (0.5 + 0.5 * np.sin(2 * np.pi * 0.08 * t)) ** 2 * 0.9
    else:                                                    # plucked arpeggio + low drum pulse
        step = 0.5
        for k in range(int(seconds / step)):
            i0 = int(k * step * SR)
            m = min(int(0.6 * SR), n - i0)
            tt = np.arange(m) / SR
            f = roots["wild"][(k // 8) % 4] * [2, 3, 4, 3][k % 4]
            out[i0:i0 + m] += np.sin(2 * np.pi * f * tt) * np.exp(-tt * 7) * 0.06
            if k % 4 == 0:
                out[i0:i0 + m] += np.sin(2 * np.pi * (70 + 40 * np.exp(-tt * 20)) * tt) * np.exp(-tt * 9) * 0.12
    out *= np.minimum(1, t / 2.0) * np.minimum(1, (seconds - t) / 2.0).clip(0)
    return 0.7 * out / (np.abs(out).max() + 1e-9)


def music_bed(seconds: float, mood: str = "dark", bpm: int = 0, seed: int = 0) -> np.ndarray:
    """Simple original background track. mood: dark | epic | upbeat | devotional | dhol | retro | noir |
    cosmic | ocean | wild."""
    if mood in ("devotional", "dhol", "retro", "noir"):
        return _indian_bed(seconds, mood, seed)
    if mood in ("cosmic", "ocean", "wild"):
        return _doc_bed(seconds, mood, seed)
    rng = np.random.default_rng(seed)
    n = int(SR * seconds)
    t = np.arange(n) / SR
    bpm = bpm or {"dark": 70, "epic": 110, "upbeat": 118}.get(mood, 90)
    beat = 60 / bpm
    root = {"dark": -36, "epic": -33, "upbeat": -29}.get(mood, -33)     # semitones from A4
    scale = SCALES["major" if mood == "upbeat" else "minor"]
    progression = [0, 5, 2, 6] if mood != "upbeat" else [0, 4, 5, 3]   # scale degrees
    bar = beat * 4
    out = np.zeros(n)
    for b in range(int(seconds / bar) + 1):
        s, e = int(b * bar * SR), min(int((b + 1) * bar * SR), n)
        if s >= n:
            break
        deg = progression[b % len(progression)]
        chord = [root + scale[(deg + k) % 7] + 12 * ((deg + k) // 7) for k in (0, 2, 4)]
        seg = _pad([_note(c) for c in chord] + [_note(chord[0] - 12)], e - s,
                   0.15 if mood == "dark" else 0.35)
        fade = np.minimum(1, np.minimum(np.arange(e - s), np.arange(e - s)[::-1]) / (0.08 * SR))
        out[s:e] += seg * fade * (0.55 if mood == "dark" else 0.4)
    # rhythm
    for k in range(int(seconds / beat) + 1):
        at = int(k * beat * SR)
        if at >= n:
            break
        if mood == "dark":                       # heartbeat: lub-dub every beat
            for off, g in ((0, 0.5), (0.18, 0.32)):
                hit = impact(0.35)[: n - at - int(off * SR)] if at + int(off * SR) < n else None
                if hit is not None:
                    i0 = at + int(off * SR)
                    out[i0:i0 + len(hit)] += hit * g * 0.6
        else:
            kick = impact(0.3)
            out[at:at + len(kick)] += kick[: n - at] * (0.55 if k % 2 == 0 else 0.3)
            if mood == "upbeat":                 # plucky arpeggio, 2 notes per beat
                for half in (0, 0.5):
                    i0 = at + int(half * beat * SR)
                    if i0 >= n:
                        continue
                    deg = progression[int(k / 4) % len(progression)] + rng.choice([0, 2, 4, 7])
                    f = _note(root + 24 + scale[deg % 7] + 12 * (deg // 7))
                    m = int(0.22 * SR)
                    tt = np.arange(m) / SR
                    pl = np.sign(np.sin(2 * np.pi * f * tt)) * 0.3 * np.exp(-tt * 14)
                    out[i0:i0 + m] += pl[: n - i0] * 0.35
            if mood == "epic" and k % 4 == 3:    # tom fill
                tom = impact(0.4)
                out[at:at + len(tom)] += tom[: n - at] * 0.4
    if mood == "dark":                            # high eerie shimmer
        out += np.sin(2 * np.pi * _note(root + 43) * t) * 0.03 * (0.5 + 0.5 * np.sin(2 * np.pi * t / 7))
    out *= np.minimum(1, t / 1.5) * np.minimum(1, (seconds - t) / 1.5).clip(0)
    return 0.7 * out / (np.abs(out).max() + 1e-9)


def duck(music: np.ndarray, voice: np.ndarray, amount: float = 0.6) -> np.ndarray:
    """Lower the music while someone is speaking (sidechain)."""
    v = np.abs(voice if voice.ndim == 1 else voice.mean(axis=1))
    win = int(0.12 * SR)
    env = np.convolve(v, np.ones(win) / win, mode="same")
    env = np.clip(env / (env.max() + 1e-9) * 4, 0, 1)
    gain = 1 - amount * env
    n = min(len(music), len(gain))
    return music[:n] * gain[:n]


